import{Z as e,e as i,f as n,a0 as o}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Integration Dispatch and Policies","description":"","frontmatter":{},"headers":[],"relativePath":"guides/integrations/integration-dispatch-and-policies.md","filePath":"guides/integrations/integration-dispatch-and-policies.md","lastUpdated":1782532814000}'),s={name:"guides/integrations/integration-dispatch-and-policies.md"};function a(r,t,d,l,h,c){return i(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="integration-dispatch-and-policies" tabindex="-1">Integration Dispatch and Policies <a class="header-anchor" href="#integration-dispatch-and-policies" aria-label="Permalink to &quot;Integration Dispatch and Policies&quot;">​</a></h1><p>Imagine a contact form that sends to Mailchimp, posts to a CRM, and fires a Slack notification — but only when the user opts in, and only after the submission is saved. Formie separates <strong>what</strong> each integration does (credentials, mapping, API calls) from <strong>when and how</strong> it runs on each submission. The form builder&#39;s Integrations tab controls that dispatch behaviour — order, queue vs immediate execution, re-run policies, and per-integration conditions — without changing your integration PHP.</p><p>This guide walks through configuring those controls on a real multi-integration form.</p><h2 id="where-dispatch-settings-live" tabindex="-1">Where Dispatch Settings Live <a class="header-anchor" href="#where-dispatch-settings-live" aria-label="Permalink to &quot;Where Dispatch Settings Live&quot;">​</a></h2><p>Open <strong>Formie → Forms → {Your Form} → Integrations</strong>. Each integration has its own settings panel. Form-level controls appear under <strong>Integrations → Settings</strong> at the bottom of the tab.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Scope</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Per integration</td><td>Whether the integration runs for this form</td></tr><tr><td><strong>Conditions</strong></td><td>Per integration</td><td>Whether the integration runs for a given submission</td></tr><tr><td><strong>Mapping / URL / list</strong></td><td>Per integration</td><td>Provider-specific configuration</td></tr><tr><td><strong>Dispatch</strong></td><td>Form</td><td>Execution order, queue vs immediate, notification timing</td></tr><tr><td><strong>Per-integration behaviour</strong></td><td>Form</td><td>When integrations re-run after the initial submission</td></tr></tbody></table><p>Integration <strong>credentials</strong> (API keys, OAuth connection) are managed under <strong>Formie → Integrations</strong> and are shared across forms. Per-form settings reference those credentials but do not duplicate them.</p><h2 id="site-scope-and-multi-site" tabindex="-1">Site Scope and Multi-Site <a class="header-anchor" href="#site-scope-and-multi-site" aria-label="Permalink to &quot;Site Scope and Multi-Site&quot;">​</a></h2><p>Forms can exist on multiple Craft sites, but integration configuration is <strong>structural</strong> — the same integrations, conditions, and dispatch plan apply on every site where the form is enabled.</p><p>What differs per site:</p><ul><li>Translated labels and messages (form builder site overrides)</li><li>The <code>siteId</code> stored on each submission</li></ul><p>Integration conditions can target site context using <code>{submission:site}</code> variables — site name and handle appear in the condition field picker. Use conditions when one form should send to different providers (or skip dispatch) based on which site received the submission.</p><p>For how site availability differs from translation, see <a href="/forms/multi-site-and-translation">Multi-Site &amp; Translation</a>.</p><h2 id="dispatch-conditions-per-integration" tabindex="-1">Dispatch Conditions (per Integration) <a class="header-anchor" href="#dispatch-conditions-per-integration" aria-label="Permalink to &quot;Dispatch Conditions (per Integration)&quot;">​</a></h2><p>Each integration can enable <strong>Conditions</strong> to control whether it runs for a particular submission. This is separate from field visibility conditions — it gates the integration trigger itself.</p><ol><li>Open the integration on the form’s Integrations tab.</li><li>Enable <strong>Conditions</strong>.</li><li>Build rules using submission fields, status, date, site name, or site handle.</li></ol><p>Conditions are evaluated at dispatch time. If rules do not match, the integration is skipped for that submission — no API call, no queue job.</p><p>Common patterns:</p><ul><li>Run a CRM integration only when status is <strong>Qualified</strong></li><li>Skip marketing integrations for submissions marked as spam (spam submissions skip dispatch by default)</li><li>Send to a regional automation endpoint only when <code>{submission:site}</code> matches a specific site handle</li></ul><p>Re-run policies and manual triggers <strong>still respect conditions</strong>. An operator cannot manually re-run an integration whose conditions fail for that submission.</p><h2 id="integration-dispatch-orchestration" tabindex="-1">Integration Dispatch Orchestration <a class="header-anchor" href="#integration-dispatch-orchestration" aria-label="Permalink to &quot;Integration Dispatch Orchestration&quot;">​</a></h2><p>When a form has <strong>two or more</strong> payload integrations enabled, <strong>Integrations → Settings → Dispatch</strong> becomes available.</p><h3 id="enable-integration-dispatch" tabindex="-1">Enable Integration Dispatch <a class="header-anchor" href="#enable-integration-dispatch" aria-label="Permalink to &quot;Enable Integration Dispatch&quot;">​</a></h3><p>Turn on dispatch to run integrations <strong>sequentially</strong> in a defined order instead of independently through the default queue.</p><table tabindex="0"><thead><tr><th>Control</th><th>Options</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Notification timing</strong></td><td>Before integrations / After integrations</td><td>When default-timed email notifications send relative to the integration sequence. Individual notifications can override this in Advanced settings.</td></tr><tr><td><strong>Failure policy</strong></td><td>Continue / Stop</td><td>Whether later integrations run when one fails</td></tr><tr><td><strong>Step list</strong></td><td>Ordered handles with mode</td><td>Execution order and queue vs immediate per integration</td></tr></tbody></table><p>Each step can run as:</p><ul><li><strong>Queued</strong> — pushed to Craft’s queue (recommended for external APIs)</li><li><strong>Immediate</strong> — runs during the submission request before the response returns</li></ul><p>Use <strong>Immediate</strong> for element integrations that must finish before notifications or the success page — User registration, Entry creation, and similar flows where the next step depends on the created element.</p><p>Formie shows a <strong>Recommended for User &amp; Entry flows</strong> shortcut that enables dispatch, sets notifications to run after integrations, marks User/Entry integrations as immediate, and configures re-run on edit for those integrations.</p><p>When dispatch is disabled, enabled integrations run independently using Formie’s global <code>useQueueForIntegrations</code> setting — see <a href="/get-started/configuration">Configuration</a>.</p><h3 id="dispatch-requires-two-active-integrations" tabindex="-1">Dispatch Requires Two Active Integrations <a class="header-anchor" href="#dispatch-requires-two-active-integrations" aria-label="Permalink to &quot;Dispatch Requires Two Active Integrations&quot;">​</a></h3><p>Orchestration only runs when at least two integrations are enabled on the form. If dispatch is enabled but only one integration is active, Formie falls back to default behaviour and shows a warning in the builder.</p><h2 id="re-run-policies" tabindex="-1">Re-Run Policies <a class="header-anchor" href="#re-run-policies" aria-label="Permalink to &quot;Re-Run Policies&quot;">​</a></h2><p>By default, integrations run <strong>once on submit</strong>. Formie adds per-integration re-run policies under <strong>Integrations → Settings → Per-integration behaviour</strong>.</p><table tabindex="0"><thead><tr><th>Policy</th><th>Runs on</th></tr></thead><tbody><tr><td><strong>Once on submit</strong></td><td>Initial front-end submission only (default)</td></tr><tr><td><strong>Also when submission is edited</strong></td><td>Submit, front-end edit, and control panel save</td></tr><tr><td><strong>Custom…</strong></td><td>Pick from: Initial submission, Front-end edit, Control panel save, Unmarked as not spam</td></tr></tbody></table><p>Re-run policies matter for Entry and User integrations that should update linked elements when an editor changes a submission in the control panel. They also apply when bulk status changes trigger a CP save.</p><p>Integration conditions still apply on re-runs. Changing a submission’s status does not bypass condition checks.</p><h2 id="plugin-wide-settings" tabindex="-1">Plugin-Wide Settings <a class="header-anchor" href="#plugin-wide-settings" aria-label="Permalink to &quot;Plugin-Wide Settings&quot;">​</a></h2><p>These plugin settings affect all forms:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Location</th><th>Recommendation</th></tr></thead><tbody><tr><td><code>useQueueForIntegrations</code></td><td><strong>Formie → Settings → General</strong></td><td>Enable on production so API calls do not slow submissions</td></tr><tr><td><code>queuePriority</code></td><td>Same</td><td>Tune if integration jobs compete with other queue work</td></tr><tr><td><code>sendIntegrationAlerts</code></td><td><strong>Formie → Settings → Integrations</strong></td><td>Email admins when an integration fails</td></tr><tr><td><code>redirectUri</code></td><td>Config / env</td><td>OAuth redirect override for multi-environment setups</td></tr></tbody></table><p>API keys and secrets should use <code>.env</code> variables. Formie resolves env syntax when settings are loaded and does not export resolved secrets to project config — see <a href="/get-started/configuration">Configuration</a>.</p><h2 id="how-dispatch-fits-the-workflow" tabindex="-1">How Dispatch Fits the Workflow <a class="header-anchor" href="#how-dispatch-fits-the-workflow" aria-label="Permalink to &quot;How Dispatch Fits the Workflow&quot;">​</a></h2><p>Integrations trigger during the <strong>dispatch</strong> stage of the submission workflow — after validation, screening, and save:</p><ol><li><code>dispatch.guardDispatchEligibility</code> — checks whether dispatch should run</li><li><code>dispatch.sendNotifications</code> — may run before or after integrations depending on dispatch plan</li><li><code>dispatch.triggerIntegrations</code> — runs enabled integrations that pass conditions and re-run policy</li><li><code>dispatch.markDispatchFinalized</code> — records completion</li></ol><p>Edit-existing and save-draft workflow modes skip most dispatch work. Edit-existing can re-run integrations when the re-run policy allows — see <a href="/developers/submission-workflow">Submission Workflow</a>.</p><p>Avoid triggering integrations from <code>Submission::EVENT_AFTER_SAVE</code>. That bypasses re-run policies, workflow idempotency, and the CP save vs workflow split. Use <code>Integrations::EVENT_BEFORE_TRIGGER_INTEGRATION</code> or <code>IntegrationTriggers</code> when you need custom dispatch.</p><h2 id="putting-it-together" tabindex="-1">Putting It Together <a class="header-anchor" href="#putting-it-together" aria-label="Permalink to &quot;Putting It Together&quot;">​</a></h2><p>A typical registration form with User, Mailchimp, and Web Request integrations might configure:</p><ol><li><strong>Dispatch enabled</strong> — User → Immediate, Mailchimp → Queued, Web Request → Queued</li><li><strong>Notification timing</strong> — After integrations (activation email needs the user element first)</li><li><strong>User integration re-run</strong> — Also when submission is edited</li><li><strong>Mailchimp conditions</strong> — Only when an Agree field is checked</li><li><strong>Global queue</strong> — <code>useQueueForIntegrations</code> enabled</li></ol><p>Submit once from the front end to create the user immediately, queue marketing and automation calls, and send the activation email after the user exists.</p>',50)])])}const p=e(s,[["render",a]]);export{u as __pageData,p as default};
